Lemma pix_obj_rc_keep_out : forall (live lv : list (Z * Z)) frs sp W (m m' : mem) pix v cv rc,
  agree_on (fun a => aclient lv frs sp a /\ outside W a) m m' ->
  (forall e, In e live -> In e lv) ->
  pix_obj_rc live m pix v cv rc ->
  (forall x, pix <= x < pix + 64 -> outside W x) ->
  (p_cmap v <> 0 -> (forall x, p_cmap v <= x < p_cmap v + 24 -> outside W x)
                   /\ (forall x, c_arr cv <= x < c_arr cv + 4 * c_nalloc cv -> outside W x)) ->
  pix_obj_rc live m' pix v cv rc.
